import React from 'react';

const ScoreCard = ({ title, score, color = 'purple' }) => {
  const roundedScore = Math.round(score || 0);

  return (
    <div className="glass-card p-5 rounded-2xl border border-scifi-600/30 transition-all duration-300 hover:scale-[1.03] flex items-center justify-between shadow-purple-glow">
      <div>
        <p className="text-xs font-mono tracking-wider text-scifi-200 uppercase mb-1">{title}</p>
        <p className="text-3xl font-heading font-extrabold text-scifi-100 glow-text-purple">
          {roundedScore}<span className="text-lg text-scifi-200 font-normal">%</span>
        </p>
      </div>

      {/* Mini Circular Purple Meter */}
      <div className="relative w-14 h-14 rounded-full flex items-center justify-center bg-scifi-950/80 shadow-deep-glow">
        <svg className="w-full h-full transform -rotate-90">
          <circle
            cx="28"
            cy="28"
            r="22"
            stroke="rgba(99, 89, 133, 0.2)"
            strokeWidth="4"
            fill="none"
          />
          <circle
            cx="28"
            cy="28"
            r="22"
            stroke="#635985"
            strokeWidth="4"
            fill="none"
            strokeDasharray={`${2 * Math.PI * 22}`}
            strokeDashoffset={`${2 * Math.PI * 22 * (1 - roundedScore / 100)}`}
            strokeLinecap="round"
          />
        </svg>
      </div>
    </div>
  );
};

export default ScoreCard;
